/* Only Qwen stage3 physical-fan sweep decorative wake, no projectile. */
(()=>{const role=window.ArenaCharacterModules.qwen,previous=role.drawEffect;role.drawEffect=function(c,e,env){if(e.kind!=='swing'||e.characterId!=='qwen'||e.stage!==3)return previous?.(c,e,env)??false;const u=Math.max(0,Math.min(1,env.u??1-e.life/e.max)),dir=e.dir||1;c.save();c.translate(e.x+dir*65,e.y-53);c.scale(dir,1);c.globalAlpha=(1-u)*.8;c.strokeStyle='#d1c3ff';c.lineWidth=1.3;c.beginPath();c.rect(-16,-14,48,52);c.clip();for(let j=0;j<3;j++){c.beginPath();c.moveTo(-10+u*9,2+j*6);c.quadraticCurveTo(5+u*12,20+j*5,22+u*7,8+j*6);c.stroke();}c.restore();return true;};})();
